        return _err("UNAUTHORIZED", "datastore unavailable")

    ready = []
    for s in snaps:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") != repo_id or s.get("status") != "ready":
            continue
        exp = _parse_iso(s.get("expires_at"))
        if exp is not None and exp <= now_dt:
            continue
        ready.append(s)

    def _snap_key(sn):
        return _parse_iso(sn.get("created_at")) or _parse_iso(sn.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    ready.sort(key=_snap_key, reverse=True)
    snapshot = ready[0] if ready else None
    if snapshot is None:
        _log("NOT_FOUND", "No ready snapshot in cache", repo_id=repo_id)
        return _err("NOT_FOUND", "No ready snapshot in cache")

    snapshot_id = snapshot.get("id")
    nodes = _load("repo_nodes.json")
    if not isinstance(nodes, list):
        _log("UNAUTHORIZED", "datastore unavailable", repo_id=repo_id, snapshot_id=snapshot_id)
        return _err("UNAUTHORIZED", "datastore unavailable")

    # Path parameter is a directory path; if caller passed a file path, return NOT_FOUND as per tool contract.
    target_dir = None
    for n in nodes:
        if not isinstance(n, dict):
            continue
        if n.get("snapshot_id") != snapshot_id or n.get("status") != "active":
            continue
        if n.get("path") == npath and n.get("kind") == "dir":
            target_dir = n
            break
        if n.get("path") == npath and n.get("kind") == "file":
            _log("NOT_FOUND", "Specified path is a file, not a directory", repo_id=repo_id, snapshot_id=snapshot_id)
            return _err("NOT_FOUND", "Specified path is a file, not a directory")

    if target_dir is None:
        _log("NOT_FOUND", "Directory not found", repo_id=repo_id, snapshot_id=snapshot_id)
        return _err("NOT_FOUND", "Directory not found")

    children_dirs = []
    for n in nodes:
        if not isinstance(n, dict):
            continue
        if n.get("snapshot_id") != snapshot_id:
            continue
        if n.get("status") != "active":
            continue
        if n.get("kind") != "dir":
            continue
        if n.get("parent_path") == npath:
            pth = n.get("path")
            if isinstance(pth, str):
                children_dirs.append(pth)

    children_dirs = sorted(set(children_dirs))
    _log("OK", repo_id=repo_id, snapshot_id=snapshot_id)
    return {"data": {"repository_id": repo_id, "snapshot_id": snapshot_id, "path": npath, "directories": children_dirs, "count": len(children_dirs)}}

