    ready.sort(key=_snap_key, reverse=True)
    snapshot = ready[0] if ready else None
    if snapshot is None:
        _log("NOT_FOUND", "No ready snapshot in cache", repo_id=repo_id)
        return _err("NOT_FOUND", "No ready snapshot in cache")

    snapshot_id = snapshot.get("id")
    nodes = _load("repo_nodes.json")
    if not isinstance(nodes, list):
        _log("UNAUTHORIZED", "datastore unavailable", repo_id=repo_id, snapshot_id=snapshot_id)
        return _err("UNAUTHORIZED", "datastore unavailable")

    node = None
    for n in nodes:
        if not isinstance(n, dict):
            continue
        if n.get("snapshot_id") != snapshot_id or n.get("status") != "active":
            continue
        if n.get("path") == npath:
            node = n
            break

    if node is None:
        _log("NOT_FOUND", "File not found", repo_id=repo_id, snapshot_id=snapshot_id)
        return _err("NOT_FOUND", "File not found")

    if node.get("kind") != "file":
        _log("NOT_FOUND", "Path is a directory, not a file", repo_id=repo_id, snapshot_id=snapshot_id)
        return _err("NOT_FOUND", "Path is a directory, not a file")

    git_sha = node.get("git_sha")
    if not isinstance(git_sha, str) or not re.fullmatch(r"[0-9a-fA-F]{40}", git_sha or ""):
        _log("NOT_FOUND", "File content not available", repo_id=repo_id, snapshot_id=snapshot_id, git_sha=git_sha)
        return _err("NOT_FOUND", "File content not available")

    blobs = _load("repo_blobs.json")
    if not isinstance(blobs, list):
        _log("UNAUTHORIZED", "datastore unavailable", repo_id=repo_id, snapshot_id=snapshot_id, git_sha=git_sha)
        return _err("UNAUTHORIZED", "datastore unavailable")

    blob = None
    for b in blobs:
        if not isinstance(b, dict):
            continue
        if b.get("git_sha") == git_sha and b.get("status") == "available":
            blob = b
            break

    # If file exceeds limit / binary, business rules say content may be missing: return metadata only (no error)
    # when node.is_binary is true or blob absent.
    if blob is None:
        data = {
            "repository_id": repo_id,
            "snapshot_id": snapshot_id,
            "path": npath,
            "git_sha": git_sha,
            "size_bytes": node.get("size_bytes"),
            "is_binary": bool(node.get("is_binary")),
            "encoding": None,
            "content": None,
            "content_size_bytes": None,
        }
        _log("OK", "Content not cached", repo_id=repo_id, snapshot_id=snapshot_id, git_sha=git_sha)
        return {"data": data}

    encoding = blob.get("encoding")
    content = blob.get("content")
    size_b = blob.get("content_size_bytes")
    if encoding not in ("utf-8", "base64") or not isinstance(content, str) or not isinstance(size_b, int) or size_b < 0:
        _log("NOT_FOUND", "File content not available", repo_id=repo_id, snapshot_id=snapshot_id, git_sha=git_sha)
        return _err("NOT_FOUND", "File content not available")

    # Validate base64 if declared
    if encoding == "base64":
        try:
            base64.b64decode(content.encode("ascii", "ignore"), validate=True)
        except Exception:
            _log("NOT_FOUND", "File content not available", repo_id=repo_id, snapshot_id=snapshot_id, git_sha=git_sha)
            return _err("NOT_FOUND", "File content not available")

    _log("OK", repo_id=repo_id, snapshot_id=snapshot_id, git_sha=git_sha)
    return {"data": {
        "repository_id": repo_id,
        "snapshot_id": snapshot_id,
        "path": npath,
        "git_sha": git_sha,
        "size_bytes": node.get("size_bytes"),
        "is_binary": bool(node.get("is_binary")),
        "encoding": encoding,
        "content": content,
        "content_size_bytes": size_b,
    }}

def getRepository(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0296000" if __import__("os").path.isdir("./environment_mix/0296000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, message=None, repo_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status,
            "message": message,
            "repo_id": repo_id,
            "ts": _now_iso(),
            "latency_ms": None,
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = _parse_iso(r.get("ts"))
            if not ts:
                continue
            if ts < window:
                break
            if r.get("endpoint") == endpoint:
                cnt += 1
                if cnt > 240:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check("getRepository")
    if rl:
        _log("getRepository", "error", rl["error"]["message"])
        return rl

    if not isinstance(id, str) or not id.strip():
        _log("getRepository", "error", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    rid = id.strip()

    try:
        repos = _load("repositories.json")
        if not isinstance(repos, list):
            repos = []
    except Exception as ex:
        _log("getRepository", "error", "Datastore error")
        return _err("CONFLICT", "Datastore error", detail=str(ex))

    repo = None
    for r in repos:
        if r.get("id") == rid:
            repo = r
            break

    if repo is None:
        _log("getRepository", "error", "Repository not found")
        return _err("NOT_FOUND", "Repository not found")

    _log("getRepository", "ok", None, repo_id=rid)
    return repo

def listRepositories(repoUrl=None, host=None, owner=None, name=None, visibility=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0296000" if __import__("os").path.isdir("./environment_mix/0296000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "tool": "listRepositories",
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-3000:]):
            ts = _parse_iso(r.get("created_at") or r.get("ts"))
            if not ts:
                continue
            if ts < window:
                break
            if r.get("tool") == "listRepositories" or r.get("endpoint") == "listRepositories":
                cnt += 1
                if cnt > 120:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _normalize_repo_url_filter(u):
        # For list filter, accept either a repo id or a URI. Do not reject repo ids.
        if u is None:
            return (None, None)
        if not isinstance(u, str) or not u.strip():
            return (None, "repoUrl must be a string")
        s = u.strip()
        if re.match(r"^ghr_repo_[0-9A-Z]+$", s):
            return (("ID", s), None)
        try:
            p = urlparse(s)
        except Exception:
            return (None, "repoUrl must be a valid URI")
        if p.scheme not in ("http", "https") or not p.netloc:
            return (None, "repoUrl must be a valid URI")
        hostx = p.netloc.lower()
        if hostx != "github.com":
            return (None, "repoUrl host must be github.com")
        pp = (p.path or "").strip()
        if pp.endswith(".git"):
            pp = pp[:-4]
        pp = pp.strip("/")
        parts = [x for x in pp.split("/") if x]
        if len(parts) < 2:
            return (None, "repoUrl must include owner and repo name")
        ownerx, namex = parts[0], parts[1]
        return (("URL", f"https://github.com/{ownerx}/{namex}"), None)

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    # Validate simple types
    if host is not None and not isinstance(host, str):
        _log("VALIDATION_ERROR", "host must be a string")
        return _err("VALIDATION_ERROR", "host must be a string")
    if owner is not None and not isinstance(owner, str):
        _log("VALIDATION_ERROR", "owner must be a string")
        return _err("VALIDATION_ERROR", "owner must be a string")
    if name is not None and not isinstance(name, str):
        _log("VALIDATION_ERROR", "name must be a string")
        return _err("VALIDATION_ERROR", "name must be a string")
    if visibility is not None:
        if not isinstance(visibility, str):
            _log("VALIDATION_ERROR", "visibility must be a string")
            return _err("VALIDATION_ERROR", "visibility must be a string")
        # Tool allows "internal"; datastore schema doesn't, but tool schema does. Accept it as filter that yields none.
        if visibility not in ("public", "private", "internal", "unknown"):
            _log("VALIDATION_ERROR", "visibility must be one of: public, private, internal, unknown")
            return _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal, unknown")
    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", "status must be a string")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "disabled", "deleted"):
            _log("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("VALIDATION_ERROR", "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "limit must be between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    repoUrl_filter, rerr = _normalize_repo_url_filter(repoUrl)
    if rerr:
        _log("VALIDATION_ERROR", rerr)
        return _err("VALIDATION_ERROR", rerr)

    repos = _load("repositories.json")
    if not isinstance(repos, list):
        _log("UNAUTHORIZED", "datastore unavailable")
        return _err("UNAUTHORIZED", "datastore unavailable")

    # Apply filters
    out = []
    for r in repos:
        if not isinstance(r, dict):
            continue
        if repoUrl_filter:
            k, v = repoUrl_filter
            if k == "ID":
                if r.get("id") != v:
                    continue
            else:
                if r.get("repo_url") != v:
                    continue
        if host is not None and r.get("host") != host:
            continue
        if owner is not None and r.get("owner") != owner:
            continue
        if name is not None and r.get("name") != name:
            continue
        if visibility is not None:
            # "internal" is not present in datastore; treat as no match.
            if visibility == "internal":
                continue
            if r.get("visibility") != visibility:
                continue
        if status is not None and r.get("status") != status:
            continue
        out.append(r)

    # Sort by updated_at desc then id
    def _sort_key(r):
        return (
            _parse_iso(r.get("updated_at")) or _parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc),
            r.get("id") or ""
        )
    out.sort(key=_sort_key, reverse=True)

    # Cursor is the last seen id (opaque enough for this datastore)
    start = 0
    if cursor:
        for i, r in enumerate(out):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = out[start:start + limit]
    has_more = (start + limit) < len(out)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _log("OK")
    return {
        "data": page,
        "meta": {
            "total": len(out),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def createRepoSnapshot(repoUrl, ref=None, force=None, **_extra):
    import json, os, datetime, time, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0296000" if __import__("os").path.isdir("./environment_mix/0296000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, message=None, repo_id=None, snapshot_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "tool": "createRepoSnapshot",
            "status": status_code,
            "message": message,
            "repo_id": repo_id,
            "snapshot_id": snapshot_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-3000:]):
            ts = _parse_iso(r.get("created_at") or r.get("ts"))
            if not ts:
                continue
            if ts < window:
                break
            if r.get("tool") == "createRepoSnapshot" or r.get("endpoint") == "createRepoSnapshot":
                cnt += 1
                if cnt > 60:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _enc(v):
            s = ""
            while v:
                v, r = divmod(v, 32)
                s = alphabet[r] + s
            return s or "0"
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(6), "big")
        return f"{prefix}{_enc(ms)}{_enc(rnd)}"

    def _normalize_repo_ref(u):
        # Accept either a GitHub URL or an existing repository id (as used in audit defect).
        if not isinstance(u, str) or not u.strip():
            return (None, None, None, None, "repoUrl is required")
        s = u.strip()
        if re.match(r"^ghr_repo_[0-9A-Z]+$", s):
            return ("ID", s, None, None, None)
        try:
            p = urlparse(s)
        except Exception:
            return (None, None, None, None, "repoUrl must be a valid URI")
        if p.scheme not in ("http", "https") or not p.netloc:
            return (None, None, None, None, "repoUrl must be a valid URI")
        host = p.netloc.lower()
        if host != "github.com":
            return (None, None, None, None, "repoUrl host must be github.com")
        pp = (p.path or "").strip()
        if pp.endswith(".git"):
            pp = pp[:-4]
        pp = pp.strip("/")
        parts = [x for x in pp.split("/") if x]
        if len(parts) < 2:
            return (None, None, None, None, "repoUrl must include owner and repo name")
        owner, name = parts[0], parts[1]
        norm_url = f"https://github.com/{owner}/{name}"
        return ("URL", norm_url, host, owner, name)

    # Validate inputs
    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    kind, a, host, owner, name = _normalize_repo_ref(repoUrl)
    if not kind:
        _log("VALIDATION_ERROR", name)
        return _err("VALIDATION_ERROR", name)

    if ref is not None and not isinstance(ref, str):
        _log("VALIDATION_ERROR", "ref must be a string")
        return _err("VALIDATION_ERROR", "ref must be a string")
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log("VALIDATION_ERROR", "force must be a boolean")
        return _err("VALIDATION_ERROR", "force must be a boolean")

    if ref is not None:
        ref = ref.strip()
        if not ref:
            _log("VALIDATION_ERROR", "ref must not be empty")
            return _err("VALIDATION_ERROR", "ref must not be empty")
        # Allow typical git refs and 40-hex
        if not re.fullmatch(r"[0-9A-Fa-f]{40}|[A-Za-z0-9._/\-]+", ref):
            _log("VALIDATION_ERROR", "ref is not a valid git ref")
            return _err("VALIDATION_ERROR", "ref is not a valid git ref")

    repos = _load("repositories.json")
    if not isinstance(repos, list):
        _log("UNAUTHORIZED", "datastore unavailable")
        return _err("UNAUTHORIZED", "datastore unavailable")

    repo = None
    if kind == "ID":
        for r in repos:
            if isinstance(r, dict) and r.get("id") == a:
                repo = r
                break
        if repo is None:
            _log("NOT_FOUND", "Repository not found", repo_id=a)
            return _err("NOT_FOUND", "Repository not found")
    else:
        norm_url = a
        for r in repos:
            if isinstance(r, dict) and r.get("repo_url") == norm_url:
                repo = r
                break
        if repo is None:
            repo = {
                "id": _gen_id("ghr_repo_"),
                "repo_url": norm_url,
                "host": "github.com",
                "owner": owner,
                "name": name,
                "default_ref": "main",
                "visibility": "unknown",
                "status": "active",
                "last_indexed_at": None,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            # enforce uniques
            for r in repos:
                if not isinstance(r, dict):
                    continue
                if r.get("repo_url") == norm_url or (r.get("host") == "github.com" and r.get("owner") == owner and r.get("name") == name):
                    repo = r
                    break
            if repo.get("created_at") == now_iso and repo.get("repo_url") == norm_url:
                repos.append(repo)
                _save("repositories.json", repos)

    repo_id = repo.get("id")
    if repo.get("status") in ("disabled", "deleted"):
        _log("CONFLICT", f"Repository is {repo.get('status')}; cannot index new snapshots", repo_id=repo_id)
        return _err("CONFLICT", f"Repository is {repo.get('status')}; cannot index new snapshots")

    if ref is None:
        ref = repo.get("default_ref") or "main"

    snaps = _load("repo_snapshots.json")
    if not isinstance(snaps, list):
        _log("UNAUTHORIZED", "datastore unavailable", repo_id=repo_id)
        return _err("UNAUTHORIZED", "datastore unavailable")

    # If a non-expired ready snapshot exists and not force, reuse (idempotent behavior)
    def _is_unexpired_ready(s):
        if s.get("status") != "ready":
            return False
        exp = _parse_iso(s.get("expires_at"))
        return exp is None or exp > now_dt

    existing_ready = None
    for s in snaps:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") == repo_id and s.get("ref") == ref and _is_unexpired_ready(s):
            existing_ready = s
            break

    if existing_ready is not None and not force:
        _log("OK", "Reused existing ready snapshot", repo_id=repo_id, snapshot_id=existing_ready.get("id"))
        return {"data": existing_ready}

    # If there's already a queued/indexing snapshot for this ref, reuse it unless force
    if not force:
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("repository_id") == repo_id and s.get("ref") == ref and s.get("status") in ("queued", "indexing"):
                _log("OK", "Reused existing in-progress snapshot", repo_id=repo_id, snapshot_id=s.get("id"))
                return {"data": s}

    # Create new queued snapshot
    new_snap = {
        "id": _gen_id("ghr_snp_"),
        "repository_id": repo_id,
        "ref": ref,
        "commit_sha": "0" * 40,
        "root_tree_sha": "0" * 40,
        "status": "queued",
        "error_message": None,
        "indexed_files_count": 0,
        "indexed_dirs_count": 0,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # unique(repository_id, ref, commit_sha) - commit_sha is placeholder; allow duplicates by picking unique placeholder
    # if collision occurs (extremely unlikely, but enforce deterministically).
    existing_keys = {(s.get("repository_id"), s.get("ref"), s.get("commit_sha")) for s in snaps if isinstance(s, dict)}
    if (repo_id, ref, new_snap["commit_sha"]) in existing_keys:
        # create a unique pseudo-commit sha marker while still satisfying length=40 hex
        # (not a real commit, but schema constraint only is length/hex)
        uniq = re.sub(r"[^0-9a-f]", "0", hex(int(time.time()*1000000))[2:])[-40:].rjust(40, "0")
        new_snap["commit_sha"] = uniq.lower()
        if (repo_id, ref, new_snap["commit_sha"]) in existing_keys:
            # last resort: random 40 hex
            new_snap["commit_sha"] = os.urandom(20).hex()

    snaps.append(new_snap)
    _save("repo_snapshots.json", snaps)
    _log("OK", "Snapshot enqueued", repo_id=repo_id, snapshot_id=new_snap["id"])
    return {"data": new_snap}

def getRepoSnapshot(id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0296000" if __import__("os").path.isdir("./environment_mix/0296000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status_code, message=None, snapshot_id=None):
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "getRepoSnapshot",
            "tool": "getRepoSnapshot",
            "status": status_code,
            "message": message,
            "snapshot_id": snapshot_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    # Rate limit: 240/min for this tool based on request_logs.json
    logs = _ensure_list(_load("request_logs.json"))
    window = now_dt - datetime.timedelta(seconds=60)
    cnt = 0
    # scan from newest backwards, stop when older than window
    for r in reversed(logs[-5000:]):
        ts = _parse_iso(r.get("created_at") or r.get("ts") or r.get("timestamp"))
        if not ts:
            continue
        if ts < window:
            break
        if r.get("tool") == "getRepoSnapshot" or r.get("endpoint") == "getRepoSnapshot":
            cnt += 1
            if cnt >= 240:
                out = _err("RATE_LIMIT", "Rate limit exceeded")
                _log("RATE_LIMIT", out["error"]["message"], snapshot_id=id if isinstance(id, str) else None)
                return out

    # Validate input
    if not isinstance(id, str) or not id.strip():
        out = _err("VALIDATION_ERROR", "Invalid 'id': must be a non-empty string")
        _log("VALIDATION_ERROR", out["error"]["message"])
        return out
    snap_id = id.strip()

    # Accept both snapshot ids and repository ids (legacy/observed behavior in audits)
    is_repo_id = bool(re.match(r"^ghr_repo_", snap_id))
    is_snapshot_id = bool(re.match(r"^ghr_snp_", snap_id))

    snapshots = _ensure_list(_load("repo_snapshots.json"))
    repositories = _ensure_list(_load("repositories.json"))

    def _by_id(rows, rid):
        for row in rows:
            if isinstance(row, dict) and row.get("id") == rid:
                return row
        return None

    repo = None
    snap = None

    if is_snapshot_id:
        snap = _by_id(snapshots, snap_id)
        if snap:
            repo = _by_id(repositories, snap.get("repository_id"))
    elif is_repo_id:
        # If a repository id is supplied, return the latest snapshot (by created_at, then updated_at)
        repo = _by_id(repositories, snap_id)
        if repo:
            # choose latest snapshot for repo regardless of status; caller asked for "a snapshot record"
            cand = [s for s in snapshots if isinstance(s, dict) and s.get("repository_id") == repo.get("id")]
            def _dt_key(s):
                c = _parse_iso(s.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                u = _parse_iso(s.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                return (c, u, s.get("id") or "")
            cand.sort(key=_dt_key, reverse=True)
            snap = cand[0] if cand else None
    else:
        # Unknown id format: still attempt exact snapshot lookup first, then treat as repository id.
        snap = _by_id(snapshots, snap_id)
        if snap:
            repo = _by_id(repositories, snap.get("repository_id"))
        else:
            repo = _by_id(repositories, snap_id)
            if repo:
                cand = [s for s in snapshots if isinstance(s, dict) and s.get("repository_id") == repo.get("id")]
                def _dt_key(s):
                    c = _parse_iso(s.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                    u = _parse_iso(s.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                    return (c, u, s.get("id") or "")
                cand.sort(key=_dt_key, reverse=True)
                snap = cand[0] if cand else None

    if not snap:
        out = _err("NOT_FOUND", "Snapshot not found")
        _log("NOT_FOUND", out["error"]["message"], snapshot_id=snap_id)
        return out

    # Authorization context is ambient; there are no explicit credentials in this tool.
    # Enforce minimal business rule: if repository is deleted/disabled, still allow viewing existing snapshot record,
    # but do not fabricate/resolve any newer snapshot; here we only return the stored row.
    # If repository FK is missing, treat as NOT_FOUND (broken reference).
    if not repo:
        out = _err("NOT_FOUND", "Repository for snapshot not found")
        _log("NOT_FOUND", out["error"]["message"], snapshot_id=snap.get("id"))
        return out

    # Return snapshot record envelope (no fabrication)
    out = {
        "snapshot": snap,
        "repository": {
            "id": repo.get("id"),
            "repo_url": repo.get("repo_url"),
            "host": repo.get("host"),
            "owner": repo.get("owner"),
            "name": repo.get("name"),
            "status": repo.get("status"),
            "visibility": repo.get("visibility"),
            "default_ref": repo.get("default_ref"),
        }
    }
    _log("OK", None, snapshot_id=snap.get("id"))
    return out

def listRepoSnapshots(repoUrl, ref=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0296000" if __import__("os").path.isdir("./environment_mix/0296000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, message=None, repo_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "tool": "listRepoSnapshots",
            "status": status_code,
            "message": message,
            "repo_id": repo_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-3000:]):
            ts = _parse_iso(r.get("created_at") or r.get("ts"))
            if not ts:
                continue
            if ts < window:
                break
            if r.get("tool") == "listRepoSnapshots" or r.get("endpoint") == "listRepoSnapshots":
                cnt += 1
                if cnt > 120:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _normalize_repo_ref(u):
        if not isinstance(u, str) or not u.strip():
            return (None, None, None, None, "repoUrl is required")
        s = u.strip()
        if re.match(r"^ghr_repo_[0-9A-Z]+$", s):
            return ("ID", s, None, None, None)
        try:
            p = urlparse(s)
        except Exception:
            return (None, None, None, None, "repoUrl must be a valid URI")
        if p.scheme not in ("http", "https") or not p.netloc:
            return (None, None, None, None, "repoUrl must be a valid URI")
        host = p.netloc.lower()
        if host != "github.com":
            return (None, None, None, None, "repoUrl host must be github.com")
        pp = (p.path or "").strip()
        if pp.endswith(".git"):
            pp = pp[:-4]
        pp = pp.strip("/")
        parts = [x for x in pp.split("/") if x]
        if len(parts) < 2:
            return (None, None, None, None, "repoUrl must include owner and repo name")
        owner, name = parts[0], parts[1]
        norm_url = f"https://github.com/{owner}/{name}"
        return ("URL", norm_url, host, owner, name)

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    kind, a, host, owner, name = _normalize_repo_ref(repoUrl)
    if not kind:
        _log("VALIDATION_ERROR", name)
        return _err("VALIDATION_ERROR", name)

    if ref is not None and not isinstance(ref, str):
        _log("VALIDATION_ERROR", "ref must be a string")
        return _err("VALIDATION_ERROR", "ref must be a string")
    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", "status must be a string")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("queued", "indexing", "ready", "failed", "expired"):
            _log("VALIDATION_ERROR", "status must be one of: queued, indexing, ready, failed, expired")
            return _err("VALIDATION_ERROR", "status must be one of: queued, indexing, ready, failed, expired")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("VALIDATION_ERROR", "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "limit must be between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    repos = _load("repositories.json")
    if not isinstance(repos, list):
        _log("UNAUTHORIZED", "datastore unavailable")
        return _err("UNAUTHORIZED", "datastore unavailable")

    repo = None
    if kind == "ID":
        for r in repos:
            if isinstance(r, dict) and r.get("id") == a:
                repo = r
                break
        if repo is None:
            _log("NOT_FOUND", "Repository not found", repo_id=a)
            return _err("NOT_FOUND", "Repository not found")
    else:
        for r in repos:
            if isinstance(r, dict) and r.get("repo_url") == a:
                repo = r
                break
        if repo is None:
            _log("NOT_FOUND", "Repository not found")
            return _err("NOT_FOUND", "Repository not found")

    repo_id = repo.get("id")

    snaps = _load("repo_snapshots.json")
    if not isinstance(snaps, list):
        _log("UNAUTHORIZED", "datastore unavailable", repo_id=repo_id)
        return _err("UNAUTHORIZED", "datastore unavailable")

    out = []
    for s in snaps:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") != repo_id:
            continue
        if ref is not None and s.get("ref") != ref:
            continue
        if status is not None and s.get("status") != status:
            continue
        out.append(s)

    def _sort_key(s):
        return (
            _parse_iso(s.get("created_at")) or _parse_iso(s.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc),
            s.get("id") or ""
        )
    out.sort(key=_sort_key, reverse=True)

    start = 0
    if cursor:
        for i, s in enumerate(out):
            if s.get("id") == cursor:
                start = i + 1
                break

    page = out[start:start + limit]
    has_more = (start + limit) < len(out)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _log("OK", repo_id=repo_id)
    return {
        "data": page,
        "meta": {
            "repository_id": repo_id,
            "total": len(out),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def updateRepository(id, defaultRef=None, status=None, **_extra):
    import json, os, datetime, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0296000" if __import__("os").path.isdir("./environment_mix/0296000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _get_request_log_collection_name():
        # Best-effort autodetect; if not present, we do not error.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _log_request(endpoint, status_code, credential_id=None, error_code=None, message=None, extra=None, started_at=None):
        logf = _get_request_log_collection_name()
        if not logf:
            return
        logs = _load(logf)
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        if started_at is None:
            started_at = now
        latency_ms = int(max(0, (now - started_at).total_seconds() * 1000))
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": now.isoformat(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
        }
        if credential_id is not None:
            row["credential_id"] = credential_id
        if error_code is not None:
            row["error_code"] = error_code
        if message is not None:
            row["message"] = message
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save(logf, logs)

    started = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "updateRepository"

    # Validate inputs (shape enforced by tool contract; validate types/enums)
    if not isinstance(id, str) or not id.strip():
        _log_request(endpoint, 400, error_code="VALIDATION_ERROR", message="id must be a non-empty string", started_at=started)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    if defaultRef is not None:
        if not isinstance(defaultRef, str) or defaultRef not in ("main", "master"):
            _log_request(endpoint, 400, error_code="VALIDATION_ERROR", message="defaultRef must be 'main' or 'master'", started_at=started)
            return _err("VALIDATION_ERROR", "defaultRef must be 'main' or 'master'", field="defaultRef")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            _log_request(endpoint, 400, error_code="VALIDATION_ERROR", message="status must be one of active, disabled, deleted", started_at=started)
            return _err("VALIDATION_ERROR", "status must be one of active, disabled, deleted", field="status")

    # Load repository
    repos = _load("repositories.json")
    if not isinstance(repos, list):
        repos = []

    repo = None
    idx = None
    for i, r in enumerate(repos):
        if isinstance(r, dict) and r.get("id") == id:
            repo = r
            idx = i
            break

    if repo is None:
        _log_request(endpoint, 404, error_code="NOT_FOUND", message="Repository not found", started_at=started)
        return _err("NOT_FOUND", "Repository not found", id=id)

    # Apply updates with lifecycle transition enforcement
    transitions = {
        "active": {"disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": set(),
    }

    changed = False

    # default_ref update
    if defaultRef is not None and defaultRef != repo.get("default_ref"):
        # Disallow changing default_ref on deleted repository? Schema doesn't explicitly prohibit; keep allowed.
        repo["default_ref"] = defaultRef
        changed = True

    # status transition
    if status is not None and status != repo.get("status"):
        current = repo.get("status")
        if current not in transitions:
            _log_request(endpoint, 409, error_code="CONFLICT", message="Current status is invalid; cannot transition", started_at=started)
            return _err("CONFLICT", "Current status is invalid; cannot transition", current_status=current)
        if status not in transitions[current]:
            # Tool description says CONFLICT for not permitted
            _log_request(endpoint, 409, error_code="CONFLICT", message="Requested status transition is not permitted", started_at=started)
            return _err(
                "CONFLICT",
                "Requested status transition is not permitted",
                from_status=current,
                to_status=status,
            )
        repo["status"] = status
        changed = True

    if not changed:
        # Return existing row; this is a successful read-like no-op, acceptable because the target row exists.
        _log_request(endpoint, 200, started_at=started)
        return {"repository": repo}

    # updated_at rule: status != 'deleted' implies updated_at set on changes
    now_iso = _now_iso()
    repo["updated_at"] = now_iso

    # If row is missing created_at, backfill to keep constraints reasonable
    if repo.get("created_at") is None:
        repo["created_at"] = now_iso

    repos[idx] = repo
    _save("repositories.json", repos)

    _log_request(endpoint, 200, started_at=started)
    return {"repository": repo}
